/**
 * Writes the index files that register generated template themes and
 * layouts (src/lib/templates/{content,blueprints}/gen/*.ts). Run after
 * adding or removing a generated file:
 *   node scripts/gen-template-index.mjs
 */
import { readdirSync, writeFileSync } from "node:fs";
import { join } from "node:path";

const ROOT = "src/lib/templates";

function files(dir) {
  return readdirSync(join(ROOT, dir))
    .filter((f) => f.endsWith(".ts") && f !== "index.ts" && !f.startsWith("."))
    .map((f) => f.slice(0, -3))
    .sort();
}

function write(dir, header, importsFor, body) {
  const names = files(dir);
  const out = [
    "// Generated by scripts/gen-template-index.mjs — do not edit by hand.",
    header,
    ...names.map((n, i) => importsFor(n, i)),
    "",
    body(names),
    "",
  ].join("\n");
  writeFileSync(join(ROOT, dir, "index.ts"), out);
  return names.length;
}

const themes = write(
  "content/gen",
  'import type { Theme } from "../../types";',
  (n, i) => `import * as m${i} from "./${n}";`,
  (names) =>
    `const modules: Record<string, unknown>[] = [${names.map((_, i) => `m${i}`).join(", ")}];\n` +
    "/** Every exported theme array from every generated content file. */\n" +
    "export const GENERATED_THEMES: Theme[] = modules.flatMap((m) =>\n" +
    "  Object.values(m).flatMap((v) => (Array.isArray(v) ? (v as Theme[]) : [])),\n" +
    ");",
);
const blueprints = write(
  "blueprints/gen",
  'import type { GenBlueprint } from "../gen-types";',
  (n, i) => `import * as m${i} from "./${n}";`,
  (names) =>
    `const modules: Record<string, unknown>[] = [${names.map((_, i) => `m${i}`).join(", ")}];\n` +
    "/** Every exported layout array from every generated blueprint file. */\n" +
    "export const GENERATED_BLUEPRINTS: GenBlueprint[] = modules.flatMap((m) =>\n" +
    "  Object.values(m).flatMap((v) => (Array.isArray(v) ? (v as GenBlueprint[]) : [])),\n" +
    ");",
);
// eslint-disable-next-line no-console -- command-line output
console.log(`registered ${themes} theme file(s) and ${blueprints} layout file(s)`);
